entries[46803] = { ["name"] = "Recipe: Spice Bread Stuffing", ["text"] = "Binds when picked up\nRequires Cooking (1)\nUse: Teaches you how to cook Spice Bread Stuffing.\n\nSpice Bread Stuffing\nDuration: 7 days (real time)\nUse: Restores 4% of your health and mana every sec for 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain [floor(cond([source value]([source value], 15), [source value] - 15, 0) * 0.554) + 4] hit rating and Stamina for 1 hour.\nSell Price: 1\nRequires Spice Bread , Autumnal Herbs", ["unresolvedValues"] = true }
entries[46804] = { ["name"] = "Recipe: Pumpkin Pie", ["text"] = "Binds when picked up\nRequires Cooking (100)\nUse: Teaches you how to bake Pumpkin Pie.\n\nPumpkin Pie\nDuration: 7 days (real time)\nUse: Restores 4% of your health and mana every sec for 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain [floor(cond([source value]([source value], 15), [source value] - 15, 0) * 0.554) + 4] Spirit and Stamina for 1 hour.\nSell Price: 1\nRequires Ripe Tirisfal Pumpkin , Honey", ["unresolvedValues"] = true }
entries[46805] = { ["name"] = "Recipe: Cranberry Chutney", ["text"] = "Binds when picked up\nRequires Cooking (160)\nUse: Teaches you how to cook Cranberry Chutney.\n\nCranberry Chutney\nDuration: 7 days (real time)\nUse: Restores 4% of your health and mana every sec for 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain [floor(cond([source value]([source value], 15), [source value] - 15, 0) * 0.6616) + 4] spell power and [floor(cond([source value]([source value], 15), [source value] - 15, 0) * 0.554) + 4] Stamina for 1 hour.\nSell Price: 1\nRequires Tangy Southfury Cranberries , Honey", ["unresolvedValues"] = true }
entries[46806] = { ["name"] = "Recipe: Candied Sweet Potato", ["text"] = "Binds when picked up\nRequires Cooking (220)\nUse: Teaches you how to cook Candied Sweet Potato.\n\nCandied Sweet Potato\nDuration: 7 days (real time)\nUse: Restores 4% of your health and mana every sec for 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain [floor(cond([source value]([source value], 15), [source value] - 15, 0) * 0.554) + 4] haste rating and Stamina for 1 hour.\nSell Price: 1\nRequires Mulgore Sweet Potato , Honey , Autumnal Herbs", ["unresolvedValues"] = true }
entries[46807] = { ["name"] = "Recipe: Slow-Roasted Turkey", ["text"] = "Binds when picked up\nRequires Cooking (280)\nUse: Teaches you how to cook Slow-Roasted Turkey.\n\nSlow-Roasted Turkey\nDuration: 7 days (real time)\nUse: Restores 4% of your health and mana every sec for 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain [floor(cond([source value]([source value], 15), [source value] - 15, 0) * 1.108) + 8] attack power and [floor(cond([source value]([source value], 15), [source value] - 15, 0) * 0.554) + 4] Stamina for 1 hour.\nSell Price: 1\nRequires Wild Turkey , Honey (2), Autumnal Herbs", ["unresolvedValues"] = true }
